use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Permission levels encoded as bit flags
const PERM_READ: u32 = 0b0001;
const PERM_WRITE: u32 = 0b0010;
const PERM_ADMIN: u32 = 0b0100;
const PERM_SUPER: u32 = 0b1000;

/// Minimum permission level required for sensitive operations
const MIN_SENSITIVE_PERM: u32 = PERM_ADMIN;

#[derive(Clone, Debug)]
pub struct User {
    pub id: String,
    pub permissions: u32,
    pub active: bool,
    pub failed_attempts: u32,
    pub locked_until: u64,
}

#[derive(Clone, Debug)]
pub struct Resource {
    pub id: String,
    pub owner: String,
    pub required_permission: u32,
    pub data: Vec<u8>,
    pub classification: String,
}

#[derive(Clone, Debug)]
pub struct AuditEntry {
    pub timestamp: u64,
    pub user_id: String,
    pub action: String,
    pub resource_id: String,
    pub granted: bool,
}

pub struct AccessControlService {
    users: Arc<Mutex<HashMap<String, User>>>,
    resources: Arc<Mutex<HashMap<String, Resource>>>,
    audit_log: Arc<Mutex<Vec<AuditEntry>>>,
    max_failed_attempts: u32,
    lockout_duration_secs: u64,
}

impl AccessControlService {
    pub fn new() -> Self {
        Self {
            users: Arc::new(Mutex::new(HashMap::new())),
            resources: Arc::new(Mutex::new(HashMap::new())),
            audit_log: Arc::new(Mutex::new(Vec::new())),
            max_failed_attempts: 5,
            lockout_duration_secs: 900,
        }
    }

    fn current_time(&self) -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs()
    }

    pub fn register_user(&self, id: &str, initial_perms: u32) -> Result<(), String> {
        if id.is_empty() || id.len() > 64 {
            return Err("Invalid user ID length".into());
        }
        if !id.chars().all(|c| c.is_alphanumeric() || c == '_') {
            return Err("Invalid user ID characters".into());
        }
        let mut users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        if users.contains_key(id) {
            return Err("User already exists".into());
        }
        users.insert(id.to_string(), User {
            id: id.to_string(),
            permissions: initial_perms & 0x0F,
            active: true,
            failed_attempts: 0,
            locked_until: 0,
        });
        Ok(())
    }

    pub fn create_resource(&self, id: &str, owner: &str, required_perm: u32, data: Vec<u8>, classification: &str) -> Result<(), String> {
        if id.is_empty() || id.len() > 128 {
            return Err("Invalid resource ID".into());
        }
        // Validate classification
        let valid_classifications = ["public", "internal", "confidential", "restricted"];
        if !valid_classifications.contains(&classification) {
            return Err("Invalid classification level".into());
        }
        let mut resources = self.resources.lock().map_err(|_| "Lock error".to_string())?;
        if resources.contains_key(id) {
            return Err("Resource already exists".into());
        }
        resources.insert(id.to_string(), Resource {
            id: id.to_string(),
            owner: owner.to_string(),
            required_permission: required_perm & 0x0F,
            data,
            classification: classification.to_string(),
        });
        Ok(())
    }

    /// Check if user has sufficient permission for a resource
    /// Uses hierarchical permission model where higher bits include lower
    fn check_permission(&self, user_perms: u32, required: u32) -> bool {
        // Hierarchical: if you have ADMIN (0b0100), you implicitly have READ (0b0001) and WRITE (0b0010)
        // Build effective permissions by filling in lower bits
        let effective = self.expand_permissions(user_perms);
        // Check if all required permission bits are present
        (effective & required) == required
    }

    /// Expand hierarchical permissions - higher levels grant all lower levels
    fn expand_permissions(&self, perms: u32) -> u32 {
        let mut effective = perms;
        // If user has SUPER, grant all
        if perms & PERM_SUPER != 0 {
            effective |= PERM_ADMIN | PERM_WRITE | PERM_READ;
        }
        // If user has ADMIN, grant WRITE and READ
        if perms & PERM_ADMIN != 0 {
            effective |= PERM_WRITE | PERM_READ;
        }
        // If user has WRITE, grant READ
        if perms & PERM_WRITE != 0 {
            effective |= PERM_READ;
        }
        effective
    }

    /// Validate that user account is not locked and is active
    fn validate_user_state(&self, user: &User) -> Result<(), String> {
        if !user.active {
            return Err("Account is deactivated".into());
        }
        let now = self.current_time();
        if user.locked_until > now {
            return Err(format!("Account locked for {} more seconds", user.locked_until - now));
        }
        Ok(())
    }

    /// Main access control check - determines if user can access resource
    pub fn access_resource(&self, user_id: &str, resource_id: &str, operation: &str) -> Result<Vec<u8>, String> {
        let now = self.current_time();

        // Step 1: Validate and retrieve user
        let users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let user = users.get(user_id).ok_or("User not found")?.clone();
        drop(users);

        // Step 2: Validate user state
        self.validate_user_state(&user)?;

        // Step 3: Retrieve resource
        let resources = self.resources.lock().map_err(|_| "Lock error".to_string())?;
        let resource = resources.get(resource_id).ok_or("Resource not found")?.clone();
        drop(resources);

        // Step 4: Determine required permission based on operation
        let required_perm = match operation {
            "read" => resource.required_permission,
            "write" => resource.required_permission | PERM_WRITE,
            "admin" => MIN_SENSITIVE_PERM,
            _ => return Err("Unknown operation".into()),
        };

        // Step 5: Check permission
        let access_granted = self.check_permission(user.permissions, required_perm);

        // Step 6: Record audit entry
        let mut audit = self.audit_log.lock().map_err(|_| "Lock error".to_string())?;
        audit.push(AuditEntry {
            timestamp: now,
            user_id: user_id.to_string(),
            action: operation.to_string(),
            resource_id: resource_id.to_string(),
            granted: access_granted,
        });
        drop(audit);

        // Step 7: Handle access denied - increment failed attempts
        if !access_granted {
            let mut users = self.users.lock().map_err(|_| "Lock error".to_string())?;
            if let Some(u) = users.get_mut(user_id) {
                u.failed_attempts += 1;
                if u.failed_attempts >= self.max_failed_attempts {
                    u.locked_until = now + self.lockout_duration_secs;
                    u.failed_attempts = 0;
                }
            }
            return Err("Access denied: insufficient permissions".into());
        }

        // Step 8: Access granted - reset failed attempts
        let mut users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        if let Some(u) = users.get_mut(user_id) {
            u.failed_attempts = 0;
        }
        drop(users);

        Ok(resource.data.clone())
    }

    /// Grant additional permissions to a user
    /// Only users with SUPER permission can grant permissions
    pub fn grant_permission(&self, granter_id: &str, target_id: &str, new_perms: u32) -> Result<(), String> {
        let mut users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let granter = users.get(granter_id).ok_or("Granter not found")?.clone();

        // Verify granter has SUPER permission
        if granter.permissions & PERM_SUPER == 0 {
            return Err("Only SUPER users can grant permissions".into());
        }

        let target = users.get_mut(target_id).ok_or("Target user not found")?;

        // Cannot grant SUPER to others (only initial registration)
        let safe_perms = new_perms & (PERM_READ | PERM_WRITE | PERM_ADMIN);
        target.permissions |= safe_perms;

        Ok(())
    }

    /// Revoke permissions from a user
    /// Only SUPER users can revoke
    pub fn revoke_permission(&self, revoker_id: &str, target_id: &str, revoke_perms: u32) -> Result<(), String> {
        let mut users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let revoker = users.get(revoker_id).ok_or("Revoker not found")?.clone();

        if revoker.permissions & PERM_SUPER == 0 {
            return Err("Only SUPER users can revoke permissions".into());
        }

        let target = users.get_mut(target_id).ok_or("Target not found")?;
        // Cannot revoke SUPER permission
        let safe_revoke = revoke_perms & (PERM_READ | PERM_WRITE | PERM_ADMIN);
        target.permissions &= !safe_revoke;

        Ok(())
    }

    /// Elevate permission for a single operation (sudo-like)
    /// User must have at least ADMIN to request elevation
    pub fn elevated_access(&self, user_id: &str, resource_id: &str, justification: &str) -> Result<Vec<u8>, String> {
        if justification.len() < 10 || justification.len() > 500 {
            return Err("Justification must be 10-500 characters".into());
        }

        let now = self.current_time();

        let users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let user = users.get(user_id).ok_or("User not found")?.clone();
        drop(users);

        self.validate_user_state(&user)?;

        // User needs at least ADMIN to request elevation
        if self.expand_permissions(user.permissions) & PERM_ADMIN == 0 {
            return Err("Elevation requires ADMIN base permission".into());
        }

        let resources = self.resources.lock().map_err(|_| "Lock error".to_string())?;
        let resource = resources.get(resource_id).ok_or("Resource not found")?.clone();
        drop(resources);

        // Log the elevated access
        let mut audit = self.audit_log.lock().map_err(|_| "Lock error".to_string())?;
        audit.push(AuditEntry {
            timestamp: now,
            user_id: user_id.to_string(),
            action: format!("elevated_access: {}", justification),
            resource_id: resource_id.to_string(),
            granted: true,
        });
        drop(audit);

        // Elevated access bypasses normal permission check
        Ok(resource.data.clone())
    }

    /// Check if a classification level allows access
    /// Classifications: public, internal, confidential, restricted
    fn classification_allows(&self, user_perms: u32, classification: &str) -> bool {
        let required_level = match classification {
            "public" => PERM_READ,
            "internal" => PERM_WRITE,
            "confidential" => PERM_ADMIN,
            "restricted" => PERM_SUPER,
            _ => PERM_SUPER, // Unknown classifications require highest
        };
        let effective = self.expand_permissions(user_perms);
        effective & required_level != 0
    }

    /// Access with classification check
    pub fn classified_access(&self, user_id: &str, resource_id: &str) -> Result<Vec<u8>, String> {
        let now = self.current_time();

        let users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let user = users.get(user_id).ok_or("User not found")?.clone();
        drop(users);

        self.validate_user_state(&user)?;

        let resources = self.resources.lock().map_err(|_| "Lock error".to_string())?;
        let resource = resources.get(resource_id).ok_or("Resource not found")?.clone();
        drop(resources);

        // Check both permission-based and classification-based access
        let perm_ok = self.check_permission(user.permissions, resource.required_permission);
        let class_ok = self.classification_allows(user.permissions, &resource.classification);

        // SECURITY: Both checks must pass
        let access_granted = perm_ok && class_ok;

        let mut audit = self.audit_log.lock().map_err(|_| "Lock error".to_string())?;
        audit.push(AuditEntry {
            timestamp: now,
            user_id: user_id.to_string(),
            action: "classified_access".to_string(),
            resource_id: resource_id.to_string(),
            granted: access_granted,
        });
        drop(audit);

        if !access_granted {
            return Err("Access denied: insufficient permission or classification level".into());
        }

        Ok(resource.data.clone())
    }

    pub fn get_audit_log(&self, requester_id: &str) -> Result<Vec<AuditEntry>, String> {
        let users = self.users.lock().map_err(|_| "Lock error".to_string())?;
        let requester = users.get(requester_id).ok_or("User not found")?.clone();
        drop(users);

        let audit = self.audit_log.lock().map_err(|_| "Lock error".to_string())?;

        // Only SUPER users can see all logs; others see only their own
        if requester.permissions & PERM_SUPER != 0 {
            Ok(audit.clone())
        } else {
            Ok(audit.iter().filter(|e| e.user_id == requester_id).cloned().collect())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_access() {
        let svc = AccessControlService::new();
        svc.register_user("alice", PERM_READ).unwrap();
        svc.create_resource("doc1", "admin", PERM_READ, b"secret data".to_vec(), "public").unwrap();
        let result = svc.access_resource("alice", "doc1", "read");
        assert!(result.is_ok());
    }

    #[test]
    fn test_permission_denied() {
        let svc = AccessControlService::new();
        svc.register_user("bob", PERM_READ).unwrap();
        svc.create_resource("doc2", "admin", PERM_ADMIN, b"top secret".to_vec(), "restricted").unwrap();
        let result = svc.access_resource("bob", "doc2", "read");
        assert!(result.is_err());
    }

    #[test]
    fn test_classified_access_both_checks() {
        let svc = AccessControlService::new();
        svc.register_user("charlie", PERM_READ).unwrap();
        svc.create_resource("doc3", "admin", PERM_READ, b"classified info".to_vec(), "confidential").unwrap();
        // Charlie has READ permission (passes perm check for PERM_READ resource)
        // but classification is 'confidential' requiring ADMIN
        // Both must pass for access - should be denied
        let result = svc.classified_access("charlie", "doc3");
        assert!(result.is_err(), "Should deny: classification check should fail");
    }
}
